def solution(text):
    """Convert each space-separated word to simple Pig Latin, leaving punctuation-only tokens unchanged."""
    parts = text.split(' ')
    out = []
    for word in parts:
        if word and any(ch.isalpha() for ch in word):
            out.append(word[1:] + word[0] + 'ay')
        else:
            out.append(word)
    return ' '.join(out)

